sp_widget.client_script:
api.controller = function($scope, $interval, $timeout, $window) {
    /* Fun on PDI - Game master console */
    var c = this;
    var REFRESH_MS = 5000;

    c.state = c.data.state;
    c.puzzles = c.data.puzzles || [];
    c.pick = activeId();
    c.limit = c.state && c.state.ok ? c.state.puzzle.timeLimitMinutes : 45;
    c.confirm = null;
    c.busy = false;
    c.message = '';
    c.messageKind = '';
    c.clockText = '';
    c.confirmText = {
        start: {
            title: 'Start the game?',
            body: 'Every registered team sees the crossword within a few seconds, and all timers start now.',
            button: 'Yes, start now', btnClass: 'gm-btn-start'
        },
        end: {
            title: 'End the game now?',
            body: 'Every team still playing is submitted with what it has filled in and scored. The leaderboard shows the final results.',
            button: 'Yes, end the game', btnClass: 'gm-btn-end'
        },
        switch: {
            title: 'Switch game?',
            body: '',
            button: 'Yes, switch', btnClass: 'gm-btn-start'
        },
        reset: {
            title: 'Reset everything?',
            body: 'All teams, members, progress, answers and points are cleared. Every table goes back to team registration.',
            button: 'Yes, reset everything', btnClass: 'gm-btn-danger'
        }
    };

    var endAt = 0;
    var refreshing = false;
    var limitTouched = false;
    var pickTouched = false;

    function activeId() {
        if (c.state && c.state.ok) return c.state.puzzle.id;
        return c.puzzles.length ? c.puzzles[0].id : null;
    }

    c.pickChanged = function() { pickTouched = true; };

    c.puzzleLabel = function(p) {
        return p.name + ' (' + p.words + ' words)' + (p.active ? ', active' : '');
    };

    syncClock();
    var poll = c.data.allowed ? $interval(refresh, REFRESH_MS) : null;
    var tick = $interval(updateClock, 1000);
    updateClock();

    $scope.$watch(function() { return c.limit; }, function(v, old) { if (v !== old) limitTouched = true; });

    function refresh() {
        if (refreshing || c.busy) return;
        refreshing = true;
        c.server.get({ action: 'state' }).then(function(r) {
            refreshing = false;
            apply(r.data.state, r.data.puzzles);
        }, function() { refreshing = false; });
    }

    function apply(state, puzzles) {
        if (!state) return;
        var oldId = c.state && c.state.ok ? c.state.puzzle.id : null;
        var newId = state.ok ? state.puzzle.id : null;
        if (oldId != newId) {               // switched game: forget the old answer key and time limit edits
            c.solution = null;
            c.showSolution = false;
            limitTouched = false;
        }
        c.state = state;
        if (puzzles) c.puzzles = puzzles;
        if (!pickTouched || oldId != newId) { c.pick = activeId(); pickTouched = false; }
        if (state.ok && !limitTouched) c.limit = state.puzzle.timeLimitMinutes;
        syncClock();
        updateClock();
    }

    function syncClock() {
        var p = c.state && c.state.ok ? c.state.puzzle : null;
        endAt = p && p.remainingSeconds !== null ? Date.now() + p.remainingSeconds * 1000 : 0;
    }

    function updateClock() {
        if (!endAt) { c.clockText = ''; return; }
        var sec = Math.max(0, Math.ceil((endAt - Date.now()) / 1000));
        var m = Math.floor(sec / 60), s = sec % 60;
        c.clockText = (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
    }

    c.stateKey = function() {
        var p = c.state.puzzle;
        if (p.state == 'ended') return 'ended';
        if (p.state != 'running') return 'not_started';
        return p.timeUp || c.clockText == '00:00' ? 'timeup' : 'running';
    };

    c.stateLabel = function() {
        return { not_started: 'Not started', running: 'Running', timeup: "Time's up", ended: 'Ended' }[c.stateKey()];
    };

    c.statusLabel = function(t) {
        if (t.status == 'submitted') {
            return { auto: 'Submitted (time up)', ended: 'Submitted (game ended)' }[t.submitType] || 'Submitted';
        }
        return {
            not_registered: 'Not registered',
            waiting: 'Waiting',
            not_opened: 'Not opened',
            in_progress: 'Playing'
        }[t.status] || t.status;
    };

    /* ---------- Start / End / Reset / time limit ---------- */

    function pickedName() {
        for (var i = 0; i < c.puzzles.length; i++) if (c.puzzles[i].id == c.pick) return c.puzzles[i].name;
        return 'the selected game';
    }

    c.ask = function(what) {
        if (what == 'switch') {
            c.confirmText['switch'].body = 'Players, the console and the leaderboard will use "' + pickedName() +
                '". Team registrations are kept; use Reset game if teams should register again.';
        }
        c.confirm = what;
    };

    c.run = function(what) {
        c.confirm = null;
        var payload = { action: what, puzzleId: c.state.ok ? c.state.puzzle.id : null, targetId: c.pick };
        call(payload, {
            start: 'The game has started. Teams will see the crossword within a few seconds.',
            end: 'The game has ended. Final results are on the Leaderboard.',
            reset: 'Everything was reset. Teams can register again.',
            'switch': 'Switched to "' + pickedName() + '".'
        }[what]);
    };

    /** Used when no game is active yet (no confirmation needed). */
    c.activateNow = function() { c.run('switch'); };

    c.saveLimit = function() {
        call({ action: 'time_limit', puzzleId: c.state.puzzle.id, minutes: c.limit }, 'Time limit saved.');
        limitTouched = false;
    };

    function call(payload, okText) {
        c.busy = true;
        c.message = '';
        c.server.get(payload).then(function(r) {
            c.busy = false;
            var res = r.data.result;
            if (res && res.ok) {
                c.messageKind = 'ok';
                c.message = okText;
                $timeout(function() { if (c.message == okText) c.message = ''; }, 6000);
            } else {
                c.messageKind = 'err';
                c.message = (res && res.message) || 'Something went wrong.';
            }
            apply(r.data.state, r.data.puzzles);
        }, function() {
            c.busy = false;
            c.messageKind = 'err';
            c.message = 'Could not reach the server.';
        });
    }


    /* ---------- crisp board at any display scaling ----------
     * Squares are sized to a whole number of screen pixels and lines are exactly
     * 1 screen pixel (2 on high-density screens), so every grid line has the same
     * thickness at 100%, 125%, 150% and 200% Windows/browser scaling. */
    var BOARD_MAX_CELL = 35;   // CSS px at 100%
    var BOARD_SIDE_SPACE = 120; // space the page needs around the board on small screens
    c.cellPx = BOARD_MAX_CELL;
    c.linePx = 1;
    c.padPx = 10;

    function sizeBoard() {
        var cols = (c.solution ? c.solution.cols : 0);
        if (!cols) return;
        var dpr = $window.devicePixelRatio || 1;
        var target = Math.min(BOARD_MAX_CELL, ($window.innerWidth - BOARD_SIDE_SPACE) / cols);
        c.cellPx = Math.max(12, Math.floor(target * dpr)) / dpr;
        c.linePx = Math.max(1, Math.round(dpr)) / dpr;
        c.padPx = Math.round(10 * dpr) / dpr;
    }

    c.boardStyle = function() {
        var px = function(v) { return (Math.round(v * 10000) / 10000) + 'px'; };
        var cell = c.cellPx, line = c.linePx, pad = c.padPx;
        // Everything is pre-computed here: the portal's SCSS compiler mangles calc() with
        // CSS variable fallbacks, so the CSS only reads these plain values.
        return '--cols: ' + (c.solution ? c.solution.cols : 0) +
            '; --cell: ' + px(cell) +
            '; --overlap: -' + px(line) +           // frame reaches one line into the next square
            '; --line: ' + px(line) +
            '; --pad: ' + px(pad) +
            '; --pad-end: ' + px(pad + line) +
            '; --num: ' + px(cell * 0.27) +
            '; --letter: ' + px(cell * 0.56);
    };

    var onResize = function() { $scope.$applyAsync(sizeBoard); };
    angular.element($window).on('resize', onResize);
    $scope.$on('$destroy', function() { angular.element($window).off('resize', onResize); });

    /* ---------- answer key ("Reveal answers") ---------- */
    c.showSolution = false;
    c.solution = null;
    c.solutionLoading = false;

    c.toggleSolution = function() {
        if (c.showSolution) { c.showSolution = false; return; }
        c.solutionLoading = true;
        c.server.get({ action: 'solution', puzzleId: c.state.puzzle.id }).then(function(r) {
            c.solutionLoading = false;
            var res = r.data.solution;
            if (!res || !res.ok) {
                c.messageKind = 'err';
                c.message = (res && res.message) || 'Could not load the answers.';
                return;
            }
            c.solution = layout(res.words);
            sizeBoard();
            c.showSolution = true;
        }, function() { c.solutionLoading = false; });
    };

    /** Same layout as the players' board: cropped to the words plus a 1-square margin. */
    function layout(words) {
        var minR = Infinity, maxR = -Infinity, minC = Infinity, maxC = -Infinity;
        words.forEach(function(w) {
            minR = Math.min(minR, w.row); minC = Math.min(minC, w.col);
            maxR = Math.max(maxR, w.direction == 'down' ? w.row + w.length - 1 : w.row);
            maxC = Math.max(maxC, w.direction == 'across' ? w.col + w.length - 1 : w.col);
        });
        var rows = words.length ? maxR - minR + 3 : 0;
        var cols = words.length ? maxC - minC + 3 : 0;
        var cells = [];
        for (var i = 0; i < rows * cols; i++) cells.push({ letter: '', number: null });
        words.forEach(function(w) {
            for (var j = 0; j < w.length; j++) {
                var r = (w.direction == 'down' ? w.row + j : w.row) - minR + 1;
                var col = (w.direction == 'across' ? w.col + j : w.col) - minC + 1;
                if (cells[r * cols + col]) cells[r * cols + col].letter = w.answer.charAt(j) || '?';
            }
            var start = cells[(w.row - minR + 1) * cols + (w.col - minC + 1)];
            if (start) start.number = w.number;
        });
        return {
            cols: cols,
            cells: cells,
            across: words.filter(function(w) { return w.direction == 'across'; }),
            down: words.filter(function(w) { return w.direction == 'down'; })
        };
    }

    $scope.$on('$destroy', function() {
        if (poll) $interval.cancel(poll);
        $interval.cancel(tick);
    });
};

sp_widget.css:
/* Fun on PDI - Game master console (BCE Global Tech palette) */
.gm {
  --brand: #00549a;
  --brand-dark: #003778;
  --ink: #1b2733;
  --muted: #5b6878;
  --surface: #f2f6fa;
  --line: #d5dee8;
  --green: #167a4e;
  --amber: #a86400;
  --red: #b3261e;
  max-width: 1140px;
  margin: 0 auto;
  padding: 20px 12px 48px;
  color: var(--ink);
}
.gm-empty { max-width: 520px; margin: 60px auto; padding: 24px; border: 2px solid var(--brand); border-radius: 8px; }

/* hero */
.gm-hero {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
  padding: 24px;
  border-radius: 8px;
  background: var(--surface);
  border-left: 8px solid var(--brand);
}
.gm-hero.is-running { border-left-color: var(--green); }
.gm-hero.is-timeup { border-left-color: var(--red); }
.gm-hero h1 { margin: 8px 0 4px; font-size: 28px; font-weight: 800; color: var(--brand-dark); }
.gm-meta { margin: 0; color: var(--muted); }
.gm-badge {
  display: inline-block;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 12px;
  background: var(--brand);
  color: #fff;
}
.is-running .gm-badge { background: var(--green); }
.is-timeup .gm-badge { background: var(--red); }
.gm-hero-side { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }
.gm-clock {
  font-size: 44px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--brand-dark);
  line-height: 1;
}
.is-timeup .gm-clock { color: var(--red); }
.gm-controls { display: flex; flex-direction: column; gap: 10px; min-width: 220px; }
.gm-label { font-size: 13px; font-weight: 700; margin: 0; }
.gm-limit-row { display: flex; gap: 8px; }
.gm-game { margin-top: 14px; }
.gm-game-row { align-items: center; flex-wrap: wrap; }
.gm-select { width: auto; min-width: 260px; max-width: 100%; background: #fff; }
.gm-empty .gm-msg { margin-top: 12px; }
.gm-field { width: 100px; font-size: 16px; padding: 6px 8px; border: 1px solid #b9c5d2; border-radius: 4px; }

/* buttons */
.gm-btn {
  display: inline-block;
  text-align: center;
  font-size: 15px;
  font-weight: 700;
  padding: 10px 18px;
  border-radius: 6px;
  border: 2px solid transparent;
  cursor: pointer;
  text-decoration: none;
}
.gm-btn[disabled] { opacity: 0.55; cursor: default; }
.gm-btn-start { background: var(--green); border-color: var(--green); color: #fff; font-size: 18px; padding: 12px 22px; }
.gm-btn-start:hover { background: #0f5f3c; }
.gm-btn-danger { background: #fff; border-color: var(--red); color: var(--red); }
.gm-btn-danger:hover { background: var(--red); color: #fff; }
.gm-modal .gm-btn-danger { background: var(--red); color: #fff; }
.gm-btn-end { background: var(--brand); border-color: var(--brand); color: #fff; font-size: 18px; padding: 12px 22px; }
.gm-btn-end:hover { background: var(--brand-dark); border-color: var(--brand-dark); }
.gm-hero.is-ended { border-left-color: var(--brand-dark); }
.is-ended .gm-badge { background: var(--brand-dark); }
.gm-modal.is-end { border-top-color: var(--brand); }
.gm-btn-ghost { background: #fff; border-color: var(--brand); color: var(--brand); }
.gm-btn-ghost:hover, .gm-btn-ghost:focus { background: var(--brand); color: #fff; text-decoration: none; }
.gm-btn:focus-visible { outline: 3px solid #9fd0ff; outline-offset: 2px; }

/* messages and checks */
.gm-msg { margin-top: 14px; padding: 12px 16px; border-radius: 6px; font-weight: 700; }
.gm-msg.is-ok { background: #e3f4ea; color: #0f5a37; }
.gm-msg.is-err { background: #fbe9e8; color: var(--red); }
.gm-checks { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 16px; }
.gm-check { padding: 12px 16px; border-radius: 6px; border: 1px solid var(--line); }
.gm-check.is-ok { background: #f1faf4; border-color: #b9e2c9; }
.gm-check.is-warn { background: #fff7e8; border-color: #f0c977; }
.gm-check.is-bad { background: #fbe9e8; border-color: #efb3ae; }
.gm-check ul { margin: 6px 0 0 18px; padding: 0; }

/* stats */
.gm-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-top: 16px; }
.gm-stat {
  padding: 14px 16px;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--muted);
  font-size: 14px;
}
.gm-stat span { display: block; font-size: 28px; font-weight: 800; color: var(--brand-dark); }

/* teams */
.gm-teams h2 { font-size: 20px; font-weight: 800; margin: 28px 0 10px; color: var(--brand-dark); }
.gm-teams h2 small { font-size: 13px; font-weight: 400; color: var(--muted); margin-left: 8px; }
.gm-table-wrap { overflow-x: auto; }
.gm-table { width: 100%; border-collapse: collapse; font-size: 14px; }
.gm-table th {
  text-align: left;
  background: var(--brand);
  color: #fff;
  padding: 8px 10px;
  font-weight: 700;
  white-space: nowrap;
}
.gm-table td { padding: 8px 10px; border-bottom: 1px solid var(--line); vertical-align: middle; }
.gm-table tbody tr:nth-child(even) td { background: #fafcfe; }
.gm-login { font-family: Consolas, Menlo, monospace; color: var(--muted); }
.gm-members { max-width: 260px; color: var(--muted); }
.gm-status { display: inline-block; padding: 2px 10px; border-radius: 10px; font-size: 12px; font-weight: 700; white-space: nowrap; }
.gm-status.is-not_registered { background: #eef1f4; color: var(--muted); }
.gm-status.is-waiting, .gm-status.is-not_opened { background: #e6eef7; color: var(--brand); }
.gm-status.is-in_progress { background: #fff3dc; color: var(--amber); }
.gm-status.is-submitted { background: #e3f4ea; color: var(--green); }
.gm-bar { width: 120px; height: 10px; border-radius: 5px; background: #e6eef7; overflow: hidden; }
.gm-bar span { display: block; height: 100%; background: var(--brand); }

/* confirmation */
.gm-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1050;
  background: rgba(0, 55, 120, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}
.gm-modal { background: #fff; border-radius: 8px; padding: 22px 24px; max-width: 440px; width: 100%; border-top: 6px solid var(--green); }
.gm-modal.is-danger { border-top-color: var(--red); }
.gm-modal h2 { margin: 0 0 8px; font-size: 20px; font-weight: 800; }
.gm-modal p { margin: 0 0 18px; color: var(--muted); }
.gm-modal-actions { display: flex; justify-content: flex-end; gap: 10px; flex-wrap: wrap; }

@media (max-width: 760px) {
  .gm-stats { grid-template-columns: 1fr 1fr; }
  .gm-checks { grid-template-columns: 1fr; }
  .gm-clock { font-size: 34px; }
}

/* answer key */
.gm-solution { margin-top: 16px; }
.gm-solution-body {
  display: flex;
  gap: 28px;
  flex-wrap: wrap;
  align-items: flex-start;
  margin-top: 14px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 8px;
}
/* same board as the players see */
.gm-board {
  flex: none;
  position: relative;
  z-index: 0;
  display: grid;
  grid-template-columns: repeat(var(--cols, 15), var(--cell, 35px));
  grid-auto-rows: var(--cell, 35px);
  background: #e9eff6;
  border-radius: 8px;
  padding: var(--pad, 10px) var(--pad-end, 11px) var(--pad-end, 11px) var(--pad, 10px);
}
.gm-sq {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #fff;
  font-weight: 800;
  font-size: var(--letter, 20px);
  color: var(--ink);
}
.gm-sq::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: var(--overlap, -1px);
  bottom: var(--overlap, -1px);
  border: var(--line, 1px) solid #00549a;
  pointer-events: none;
  z-index: 1;
}
.gm-sq.is-block { background: transparent; }
.gm-sq.is-block::after { display: none; }
.gm-sq-num { position: absolute; z-index: 2; top: 1px; left: 2px; font-size: var(--num); line-height: 1; font-weight: 700; color: var(--ink); }
.gm-key { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; flex: 1; min-width: 300px; }
.gm-key h3 { margin: 0 0 6px; font-size: 16px; font-weight: 800; color: var(--brand-dark); }
.gm-key ol { list-style: none; margin: 0; padding: 0; }
.gm-key li { padding: 4px 0; line-height: 1.4; }
.gm-key li b { color: var(--brand); display: inline-block; min-width: 20px; }
.gm-key li strong { letter-spacing: 0.06em; margin-right: 6px; }
.gm-key li span { color: var(--muted); font-size: 13px; }

sp_widget.script:
(function() {
    /* Fun on PDI - Game master console (server script)
     * input.action: 'state' (refresh), 'start', 'end', 'reset', 'time_limit', 'solution', 'switch'
     */
    data.allowed = gs.hasRole('x_1802710_fun_on_0.game_master');
    if (!data.allowed) return;

    var svc = new FunCrosswordService();

    if (input && input.action) {
        if (input.action == 'start') {
            data.result = svc.startGame(input.puzzleId);
        } else if (input.action == 'end') {
            data.result = svc.endGame(input.puzzleId);
        } else if (input.action == 'reset') {
            data.result = svc.resetGame(input.puzzleId);
        } else if (input.action == 'solution') {
            data.solution = svc.getSolution(input.puzzleId);
            return;
        } else if (input.action == 'switch') {
            data.result = svc.setActivePuzzle(input.targetId);
        } else if (input.action == 'time_limit') {
            data.result = svc.setTimeLimit(input.puzzleId, input.minutes);
        }
    }
    data.state = svc.getConsoleState();
    data.puzzles = svc.listPuzzles();
})();
